float big = 1e8f;
float a = (big + 1f) - big;   // 0: 1e8 + 1 rounds back to 1e8
float b = (big - big) + 1f;   // 1: the same numbers in another order

// a vectorized sum is 8 partial sums added up at the end: another order
// a * b + c as one FMA instruction: one rounding instead of two
// sin, exp, pow: each library and instruction set has its own approximation

// Strict: two roundings, round(round(a * b) + c)
float r1 = a * b + c;

// one rounding, round(a * b + c): more accurate, but different bits
// Fast may fuse r1 into an FMA too; math.mad says so explicitly:
// "with fast math on some architectures it could be converted to an FMA"
float r2 = math.mad(a, b, c);

[BurstCompile]                                        // FloatMode.Default = Strict
struct PhysicsStepJob : IJob { public void Execute() { } }

[BurstCompile(FloatMode = FloatMode.Fast)]           // reorder, reciprocals, FMA
struct SparksJob : IJob { public void Execute() { } }

[BurstCompile(FloatMode = FloatMode.Deterministic)]  // Burst 1.8.25+, 64-bit only
struct LockstepJob : IJob { public void Execute() { } }

// a default for a whole assembly, written above the types in a file:
// [assembly: BurstCompile(FloatMode = FloatMode.Deterministic)]

// FloatPrecision: how accurate math.sin, math.exp, math.pow... are, in ulp
[BurstCompile(FloatPrecision.Low, FloatMode.Fast)]   // a visual effect
struct WaveJob : IJobParallelFor
{
    public NativeArray<float3> points;
    public float time;
    public void Execute(int i)
    {
        float3 p = points[i];
        p.y = math.sin(p.x + time);   // Low: up to 350 ulp for sin
        points[i] = p;
    }
}

// same inputs, same order, same build and CPU: the same bits every run
// NOT promised in Strict or Fast: x64 vs ARM64, an SSE4 vs an AVX2 code path,
// Burst vs Mono/IL2CPP for the same formula

// the order is yours to fix; no FloatMode does it for you
NativeQueue<float> hits;   // filled from a parallel job via ParallelWriter
float total = 0f;
while (hits.TryDequeue(out float d))
    total += d;            // arrival order differs between runs: so does the sum

// 16.16 fixed point: the value times 65536, stored in an int
public struct Fix
{
    public int raw;
    public static Fix FromInt(int v) => new Fix { raw = v << 16 };
    public static Fix operator +(Fix a, Fix b) => new Fix { raw = a.raw + b.raw };
    public static Fix operator *(Fix a, Fix b)
        => new Fix { raw = (int)(((long)a.raw * b.raw) >> 16) };
}
// integer math gives the same bits on every CPU and in every runtime;
// the price: a narrow range, overflow, and your own sqrt and sin

