using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;

// sparks: purely visual, speed over accuracy
[BurstCompile(FloatPrecision.Low, FloatMode.Fast)]
struct ParticleJob : IJobParallelFor
{
    public NativeArray<float3> pos;
    [ReadOnly] public NativeArray<float3> vel;
    public float dt;
    public void Execute(int i) => pos[i] += vel[i] * dt;
}

// lockstep simulation: every 64-bit client must get the same bits
[BurstCompile(FloatMode = FloatMode.Deterministic)]
struct SimStepJob : IJob
{
    public NativeArray<float3> unitPos;
    public float dt;
    public void Execute()
    {
        for (int i = 0; i < unitPos.Length; i++)
            unitPos[i] += new float3(0f, 0f, 1f) * dt;
    }
}
